pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player) public {
        vm.assume(player != address(this) && player != address(c) && player != address(0));
        vm.deal(player, 10 ether);
        uint bankStart = address(c.bank()).balance;
        uint playerStart = player.balance;
        uint potBefore = c.pot();
        vm.prank(player);
        (bool success, ) = address(c).call{value: 10}(abi.encodeWithSelector(c.play.selector));
        if (success) {
            uint potAfter = c.pot();
            if (potAfter == 0) {
                // Player won
                uint expectedPlayerGain = potBefore + 10 - 1;
                uint expectedBankGain = 1;
                assertTrue(player.balance == playerStart - 10 + expectedPlayerGain);
